const mysql=require("mysql2/promise"),{getTargetConfig:getTargetConfig}=require("../db.helper");async function seedLegacyTableMap(){const e=getTargetConfig(),n=await mysql.createConnection(e);try{const e=[["HST_ANADOSYA","Patient","PATIENT",5],["HST_GELISLER","Appointment","APPOINTMENT",10],["HST_ISLEMLER","InvoiceItem","FINANCE",null],["TAHSILAT","Payment","FINANCE",null],["KULLANICILAR","User","SETTINGS",1],["STOK","InventoryItem","INVENTORY",null],["TETKIK","Service","SETTINGS",null],["EPIKRIZ","Examination","CLINIC",null],["HST_TIBBI_EPIKRIZ","Examination","CLINIC",null],["RANDEVU","Appointment","APPOINTMENT",null]],t="\n            INSERT INTO map_legacy_tables (legacy_table_name, record_type, module, legacy_table_id)\n            VALUES ?\n            ON DUPLICATE KEY UPDATE\n                record_type = VALUES(record_type),\n                module = VALUES(module),\n                legacy_table_id = VALUES(legacy_table_id) -- Update ID if we provide it\n        ";await n.query(t,[e])}catch(e){process.exit(1)}finally{await n.end()}}seedLegacyTableMap();